export type ForestLayer = keyof typeof FOREST_LAYERS;

/** The forest is drawn on a 1200 wide frame; this is its lower part, 280 tall. */
export const FOREST_FRAME = { width: 1200, height: 280, top: 500 } as const;

const svg = (viewBox: string, body: string): string =>
  `data:image/svg+xml,${encodeURIComponent(
    `<svg xmlns="http://www.w3.org/2000/svg" viewBox="${viewBox}">${body}</svg>`,
  )}`;

/** One layer of the forest as a data URI whose alpha is its silhouette. */
export const forestMask = (layer: ForestLayer): string =>
  svg(
    `0 ${FOREST_FRAME.top} ${FOREST_FRAME.width} ${FOREST_FRAME.height}`,
    `<defs><g id="t" fill="#000">${SPRUCE}</g></defs>` +
      FOREST_LAYERS[layer]
        .map(([x, y, s]) => `<use href="#t" transform="translate(${x} ${y}) scale(${s})"/>`)
        .join(''),
  );


